python3 - <<'PY'
from pathlib import Path
p = Path('tests/src/unit-udt.cpp')
s = p.read_text()
s = s.replace('#include <map>\n', '#include <cstdint>\n#include <limits>\n#include <map>\n', 1)
s = s.replace('#include <string>\n', '#include <string>\n#include <type_traits>\n', 1)
marker = 'TEST_CASE("basic usage" * doctest::test_suite("udt"))\n'
addition = '''TEST_CASE_TEMPLATE("default enum serialization" * doctest::test_suite("udt"), T,
                   std::int8_t, std::uint8_t, std::int16_t, std::uint16_t,
                   std::int32_t, std::uint32_t, std::int64_t, std::uint64_t)
{
    enum class scoped_enum : T {};
    enum unscoped_enum : T {};

    const T max = (std::numeric_limits<T>::max)();
    for (const T value : {(std::numeric_limits<T>::min)(), T(0), T(1),
                         static_cast<T>(max / 2), static_cast<T>(max / 2 + 1),
                         static_cast<T>(max - 1), max})
    {
        CAPTURE(value);
        const auto scoped = static_cast<scoped_enum>(value);
        const auto unscoped = static_cast<unscoped_enum>(value);
        const json j = scoped;
        const json unscoped_json = unscoped;

        CHECK(j == json(value));
        CHECK(j.type() == json(value).type());
        CHECK(j.is_number_unsigned() == std::is_unsigned<T>::value);
        CHECK(j.dump() == std::to_string(value));
        CHECK(j.get<scoped_enum>() == scoped);
        CHECK(json::parse(j.dump()).get<scoped_enum>() == scoped);

        CHECK(unscoped_json == j);
        CHECK(unscoped_json.type() == j.type());
        CHECK(unscoped_json.get<unscoped_enum>() == unscoped);
        CHECK(json::parse(unscoped_json.dump()).get<unscoped_enum>() == unscoped);
    }
}

'''
assert s.count(marker) == 1
p.write_text(s.replace(marker, addition + marker, 1))
